        long nilai = 0;
        String menipis = "";
        for (String b : Files.readAllLines(Paths.get("stok-uji.csv"))) {
            String[] d = b.split(";");
            int stok = Integer.parseInt(d[1]);
            nilai += (long) stok * Integer.parseInt(d[2]);
            if (stok < 5) {
                menipis += d[0] + " ";
            }
        }
        System.out.println("Nilai stok: " + nilai);
        System.out.println("Menipis: " + menipis.trim());
    }
}

