import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static final Path FILE = Paths.get("stok-proyek.csv");

    public static void main(String[] args) throws IOException {
        Files.deleteIfExists(FILE);
        List<String[]> data = new ArrayList<>();
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            String perintah = in.nextLine();
            if (perintah.startsWith("tambah ")) {
                data.add(perintah.substring(7).split(";"));
            } else if (perintah.equals("simpan")) {
                List<String> baris = new ArrayList<>();
                for (String[] d : data) {
                    baris.add(String.join(";", d));
                }
                Files.write(FILE, baris);
            } else if (perintah.equals("laporan")) {
                long nilai = 0;
                for (String b : Files.readAllLines(FILE)) {
                    String[] d = b.split(";");
                    System.out.println(d[0] + ": " + d[1] + " x " + d[2]);
                    nilai += Long.parseLong(d[1]) * Long.parseLong(d[2]);
                }
                System.out.println("Nilai: " + nilai);
            }
        }
    }
}
